// W5_PRIOR: attention/prompts/W5_PRIOR.md
const W5_PRIOR = c => (_need('W5_PRIOR', c, { received: 'flag', state: 'text', finding: 'text', at: 'text' }), `${c.received ? `Review comment the author received` : `Earlier finding`} (${c.state}): ${c.finding}${c.at ? ` (at ${c.at})` : ''}. Where does it stand now in this PR, and what is left?`)

// W5_REAL_TOOL: attention/prompts/W5_REAL_TOOL.md
const W5_REAL_TOOL = c => (_need('W5_REAL_TOOL', c, {  }), `[s13.3] Which validations existed in this repository before this PR and make a real tool process things (tests or CI steps that pass input through a real parser, renderer or compiler)? Does what this PR adds ride that path? If not, it is a hole to fix [s13.4].`)

