  const met = new Map()   // parent -> the nodes it met
  for (const part of parts) for (const p of new Set(part.flatMap(id => upOf(byId.get(id))))) {
    if (!met.has(p)) met.set(p, new Set())
    part.forEach(x => met.get(p).add(x))
  }
  if (!met.size) return
