  if (ids.some(id => up.has(id))) {
    const mine = fresh.filter(id => up.has(id))   // the nodes of its line it repeats
    if (mine.length) repairs.foldIntoOwnLine.push(`${p}: ${line1(question)} (${mine.join(', ')})`)
    markUnverified(p)
    return 'seen'
  }
  let unsure = false
